CREATE POLICY company_owner_read_delete_grants ON public.company_permanent_delete_grants FOR SELECT TO authenticated USING (company_id=public.current_company_id() AND EXISTS (SELECT 1 FROM public.company_memberships m WHERE m.company_id=company_permanent_delete_grants.company_id AND m.user_id=auth.uid() AND m.is_active AND m.role='company_owner')); GRANT SELECT ON public.company_permanent_delete_grants TO authenticated;